#row.label in GreaterThan(Q1,0) for question with 0 or 1 columns, row.label in GreaterThan(Q1,0,'c1,c2') for question with multiple columns
def GreaterThan(qid,val,*colnames):
  s = []
  if not colnames:
      for eachRow in [row for row in qid.rows if row.displayed]:
          if eachRow.val gt val:
              s.append(eachRow.label) 
  else:
      colstr = ','.join(colnames)
      colcount = colstr.split(',')
      for eachRow in [row for row in qid.rows if row.displayed]:
          for eachCol in colcount:
              if qid.attr(str(eachRow.label)).attr(eachCol).val gt val:
                  s.append(eachRow.label)                 
  return s

#row.label in LessThan(Q1,5)  
def LessThan(qid,val,*colnames):
  s = []
  if not colnames:
      for eachRow in [row for row in qid.rows if row.displayed]:
          if eachRow.val lt val:
              s.append(eachRow.label) 
  else:
      colstr = ','.join(colnames)
      colcount = colstr.split(',')
      for eachRow in [row for row in qid.rows if row.displayed]:
          for eachCol in colcount:
              if qid.attr(str(eachRow.label)).attr(eachCol).val lt val:
                  s.append(eachRow.label)                 
  return s 

#row.label in EqualTo(Q1,5)  
def EqualTo(qid,val,*colnames):
  s = []
  if not colnames:
      for eachRow in [row for row in qid.rows if row.displayed]:
          if eachRow.val == val:
              s.append(eachRow.label) 
  else:
      colstr = ','.join(colnames)
      colcount = colstr.split(',')
      for eachRow in [row for row in qid.rows if row.displayed]:
          for eachCol in colcount:
              if qid.attr(str(eachRow.label)).attr(eachCol).val == val:
                  s.append(eachRow.label)               
  return s 

#row.label in EqualToSelect(Q1,'c3,c4,c5')  
def EqualToSelect(qid,colnames):
    s = []
    colcount = colnames.split(',')
    for eachRow in [row for row in qid.rows if row.displayed]:
        for eachCol in colcount:
            if qid.attr(str(eachRow.label)).attr(eachCol):
                s.append(eachRow.label)               
    return s  

#setZero(Q1)
def setZero(qid):
  if qid.displayed:
    for eachRow in [row for row in qid.rows if row.displayed]:
      for eachCol in [col for col in qid.cols if col.displayed]:
        if eachRow[eachCol.index].val in ['', None]:
          eachRow[eachCol.index].val = 0  

#setZero2(Q1)
def setZero2(qid):
  if qid.displayed:
    for eachRow in qid.rows:
      for eachCol in qid.cols:
        if eachRow[eachCol.index].val in ['', None]:
          eachRow[eachCol.index].val = 0                

#clearForm(Q1) - Clear data from a question 
def clearForm(qid):
  if qid.cols:
    for eachRow in qid.rows:
      for eachCol in qid.cols:
        qid[eachRow][eachCol].val = None  
  else:
    for eachRow in qid.rows:        
      qid[eachRow].val = None 

#CopyForm(Q1,Q2.c1) to copy from Q1 to Q2.c1, CopyForm(Q1,Q2.c1,'c2') to copy from Q1.c2 to Q2.c1
def CopyForm(copy,paste,*colname):
    if not colname:
        for eachRow in [row for row in copy.rows if row.displayed]:
            paste.attr(str(eachRow.label)).val = eachRow.val
    else:
        colstr = ','.join(colname)
        colcount = colstr.split(',')
        eachCol = colcount[0]
        for eachRow in [row for row in copy.rows if row.displayed]:
            paste.attr(str(eachRow.label)).val = copy.attr(str(eachRow.label)).attr(eachCol).val  

#ValidateSum(Q1,'lt',10) for static sum, ValidateSum(Q1.c1,'lt',Q0.r1.val) for dynamic value in c1 only
def ValidateSum(qid,sCheck,iNum):
    if sCheck=='lt':
        if qid.sum ge iNum:
            error(res.sum_lt %iNum)
    if sCheck=='le':
        if qid.sum gt iNum:
            error(res.sum_le %iNum)  
    if sCheck=='gt':
        if qid.sum le iNum:
            error(res.sum_gt %iNum) 
    if sCheck=='ge':
        if qid.sum lt iNum:
            error(res.sum_ge %iNum)
    if sCheck=='equal':
        if qid.sum != iNum:
            error(res.sum_equal %iNum)        

##ValidateNumberRows(Q1,'lt',10) for 0 or 1 columns or ValidateNumberRows(Q1,'lt',10,'c1') to check specific column
def ValidateNumberRows(qid,sCheck,iNum,*colnames):
    if not colnames:
        for eachRow in [row for row in qid.rows if row.displayed]:
            if sCheck=='lt':
                if eachRow.val ge iNum:
                    error(res.row_lt %(eachRow.text, iNum), eachRow)
            if sCheck=='le':
                if eachRow.val gt iNum:
                    error(res.row_le %(eachRow.text, iNum), eachRow)  
            if sCheck=='gt':
                if eachRow.val le iNum:
                    error(res.row_gt %(eachRow.text, iNum), eachRow) 
            if sCheck=='ge':
                if eachRow.val lt iNum:
                    error(res.row_ge %(eachRow.text, iNum), eachRow)     
            if sCheck=='equal':
                if eachRow.val != iNum:
                    error(res.row_equal %(eachRow.text, iNum), eachRow)  
    else:
        colstr = ','.join(colnames)
        colcount = colstr.split(',')
        for eachRow in [row for row in qid.rows if row.displayed]:
            for eachCol in colcount:
              if sCheck=='lt':
                  if qid.attr(str(eachRow.label)).attr(eachCol).val ge iNum:
                      error(res.row_lt %(eachRow.text, iNum), eachRow)
              if sCheck=='le':
                  if qid.attr(str(eachRow.label)).attr(eachCol).val gt iNum:
                      error(res.row_le %(eachRow.text, iNum), eachRow)  
              if sCheck=='gt':
                  if qid.attr(str(eachRow.label)).attr(eachCol).val le iNum:
                      error(res.row_gt %(eachRow.text, iNum), eachRow) 
              if sCheck=='ge':
                  if qid.attr(str(eachRow.label)).attr(eachCol).val lt iNum:
                      error(res.row_ge %(eachRow.text, iNum), eachRow)     
              if sCheck=='equal':
                  if qid.attr(str(eachRow.label)).attr(eachCol).val != iNum:
                      error(res.row_equal %(eachRow.text, iNum), eachRow)                                               


#ValidateDKRows('any') if any box in row is required or ValidateDKRows('all') if all boxes are required
def ValidateDKRows(anyall):
  qid = this.label
  qidDK = eval(qid+'dk')
  for eachRow in [row for row in this.rows if row.displayed]:
      if anyall=='all':
          for eachCol in [col for col in this.cols if col.displayed]:
              if eachRow[eachCol] and qidDK.rows[eachRow.index]:
                  error(res.VDK %(eachRow.text,qidDK.cols[0].text), eachRow)
              elif not eachRow[eachCol] and not qidDK.rows[eachRow.index]:  
                  error(res.VDK %(eachRow.text,qidDK.cols[0].text), eachRow)
      else:
        if eachRow.any and qidDK.rows[eachRow.index]:
            error(res.VDK %(eachRow.text,qidDK.cols[0].text), eachRow)
        elif not eachRow.any and not qidDK.rows[eachRow.index]:  
            error(res.VDK %(eachRow.text,qidDK.cols[0].text), eachRow)

