#ValidateOEWordLength(q8.r1,1,5) to check if q8.r1 is between 1 and 5 words
def ValidateOEWordLength(qid,lo,hi):
    a = qid.val.split(" ")
    if (len(a) gt hi or len(a) lt lo):
        error(res.oelength %(lo, hi))

#OtherSpecNumeric('r3') for 0 or 1 columns, OtherSpecNumeric('r3','c1,c2') for multiple columns
def OtherSpecNumeric(rowname,*colname):
  if not gv.isSST():
    if not colname:
        if this.attr(rowname).val gt 0 and this.attr(rowname).open.strip() == '':
            this.attr(rowname).styles.ss.rowClassNames = "oeError" 
            error(this.lget("extraInfo"), this.attr(rowname))     
    else:
        colstr = ','.join(colname)
        colcount = colstr.split(',')
        for eachCol in colcount:
            if this.attr(rowname).attr(eachCol).val gt 0 and this.attr(rowname).open.strip() == '':
                this.attr(rowname).styles.ss.rowClassNames = "oeError" 
                error(this.lget("extraInfo"), this.attr(rowname))

